export const CATEGORIES = ['Minimal', 'Nude', 'Floral', 'Bridal', 'Glam', 'Chrome', 'Seasonal'] as const;
export type Category = (typeof CATEGORIES)[number];

export const SHAPES = ['Almond', 'Square', 'Stiletto'] as const;
export type Shape = (typeof SHAPES)[number];

export const SIZES = ['S', 'M', 'L'] as const;

export type Product = {
  slug: string;
  name: string;
  tagline: string;
  description: string;
  price: number;
  /** original price, shown struck through when higher than price */
  mrp?: number;
  category: Category;
  shape: Shape;
  images: string[];
  featured?: boolean;
};

export const img = (id: string, w: 600 | 1200 = 600) => `/images/${id}-${w}.webp`;
export const ogImg = (id: string) => `/images/${id}-og.jpg`;

